            new Quote { Id = "https://ar.wikiquote.org/wiki/عبد_الرحمن_منيف", Text = "المنفى المكان البارد، الموحش، الذي يشعرك دائما أنك غريب، زائد، وغير مـرغوب فيه، المكان الذي تفترضه مـحطة أو مؤقتا، فيصبح لاصقا بك كالعلامة الفارقة، وربما لأنه مؤقت يصبح وحده الأبدي، كالقبر، لا يمكن الهروب منه أو مغادرته. حتى الفرح والمسرات الصغيرة، وأيضا الانتصارات العابرة أو الموهومة، إن لها في المنفى مذاقا مختلفا، انها ليست لك. أنها مؤقتة، هشة، وتتحول بسرعة إلى حزن كاوٍ، وإلى بكاء لا يعرف التوقف. أما كيف تذوب وتتراجع كالحلم، ولا تشبه مثيلاتها التي تحدث في الوطن، فإن الأمر سرًا يستعصي على الفهم أو التفسير.", Author = "عبد الرحمن منيف" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/عبد_الرحمن_منيف", Text = "الوطن ليس التراب أو المكان الذي يولد فيه الإنسان، وإنما المكان الذي يستطيع فيه أن يتحرك", Author = "عبد الرحمن منيف" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/عبد_الرحمن_منيف", Text = "إن الكتابة بإختصار رحلة مليئة بالمتعة والعذاب", Author = "عبد الرحمن منيف" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/عبد_الرحمن_منيف", Text = "الجلاد لم يُولد من الجدار، ولم يهبط من الفضاء. نحن الذين خلقناه ، كما خلق الإنسان القديم آلهته. نحن الذين خلقنا الجلادين ونحن الذين سمحنا بإستمرار السجون لقد فعلنا ذلك من خلال تساهلنا وتنازلنا عن حقوقِنا، ومن خلال استسلامنا لمجموعة من الأوهامِ والأصنام، ثم لما أصبحنا الضحايا لم نعد نعرف كيف نتعامل مع هذهِ الحالة.", Author = "عبد الرحمن منيف" },
